@register.simple_tag
def social_icon(platform, variant="filled", size=24):
    """Render a Tabler SVG icon for the given social platform."""
    data = ICONS.get(platform)
    if not data:
        return ""
    path = data.get(variant) or next(
        (v for v in data.values() if v is not None), None
    )
    if not path:
        return ""
    is_filled = variant in data and data[variant] is not None and variant == "filled"
    if is_filled:
        attrs = 'fill="currentColor"'
    else:
        attrs = 'fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"'
    return mark_safe(
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" '
        f'viewBox="0 0 24 24" {attrs} class="ks-social-icon">'
        f"{path}</svg>"
    )
